import java.util.function.*;
import java.util.List;

class LambdaBasics {
    interface Discount { double apply(double amount); }   // functional interface tự viết

    static double total(List<Double> items, Discount rule) {
        double sum = 0;
        for (double i : items) sum += rule.apply(i);
        return sum;
    }

    public static void main(String[] args) {
        double rate = 0.9;                 // effectively final -> capture được
        System.out.println(total(List.of(100.0, 200.0), a -> a * rate));  // 270.0

        // 4 nhóm functional interface hay dùng nhất
        Predicate<String> notBlank = s -> !s.isBlank();
        Function<String, Integer> length = String::length;      // method reference
        Supplier<List<String>> factory = List::of;
        Consumer<String> printer = System.out::println;

        if (notBlank.test("abc")) printer.accept("len=" + length.apply("abc"));
        System.out.println(factory.get().size());

        // compose: ghép hành vi thay vì viết lại
        Function<String, Integer> lengthTimesTwo = length.andThen(n -> n * 2);
        System.out.println(lengthTimesTwo.apply("abcd"));       // 8
    }
}

import java.util.List;
import java.util.stream.Collectors;

class ProductFilterDemo {
    record Product(String name, double price, boolean inStock) {}

    List<Product> availableUnder(List<Product> products, double maxPrice) {
        return products.stream()
                .filter(p -> p.inStock() && p.price() <= maxPrice)
                .collect(Collectors.toList());
    }
}

import java.util.*;
import java.util.stream.*;

class PipelineDemo {
    public static void main(String[] args) {
        // lazy: không in gì vì thiếu terminal operation
        Stream<Integer> lazy = Stream.of(1, 2, 3).peek(n -> System.out.println("seen " + n));
        System.out.println("chưa chạy gì");

        // short-circuit: chỉ xử lý tới khi tìm thấy
        Optional<Integer> firstEven = Stream.of(1, 3, 4, 6)
                .peek(n -> System.out.println("check " + n))
                .filter(n -> n % 2 == 0)
                .findFirst();                       // dừng ngay tại 4
        System.out.println(firstEven.orElse(-1));

        // stream chỉ dùng một lần
        Stream<Integer> once = Stream.of(1, 2);
        once.count();
        try {
            once.count();
        } catch (IllegalStateException e) {
            System.out.println("stream đã bị tiêu thụ");
        }

        // flatMap: làm phẳng cấu trúc lồng nhau
        List<List<String>> nested = List.of(List.of("a", "b"), List.of("c"));
        System.out.println(nested.stream().flatMap(List::stream).toList()); // [a, b, c]
    }
}

import java.util.*;
import java.util.stream.*;

class CollectorsDemo {
    record Order(String customer, String status, double amount) {}

    public static void main(String[] args) {
        List<Order> orders = List.of(
                new Order("an", "PAID", 100),
                new Order("an", "NEW", 50),
                new Order("binh", "PAID", 300));

        Map<String, List<Order>> byCustomer =
                orders.stream().collect(Collectors.groupingBy(Order::customer));

        Map<String, Double> totalByCustomer = orders.stream()
                .collect(Collectors.groupingBy(Order::customer,
                         Collectors.summingDouble(Order::amount)));

        Map<String, Long> countByStatus = orders.stream()
                .collect(Collectors.groupingBy(Order::status, Collectors.counting()));

        String names = orders.stream().map(Order::customer)
                .distinct().collect(Collectors.joining(", "));

        System.out.println(byCustomer.keySet() + " " + totalByCustomer
                + " " + countByStatus + " [" + names + "]");

        // toMap: NÉM IllegalStateException khi khóa trùng -> phải có merge function
        Map<String, Double> latest = orders.stream()
                .collect(Collectors.toMap(Order::customer, Order::amount, (a, b) -> b));
        System.out.println(latest);
    }
}

import java.util.Optional;

class OptionalDemo {
    record Address(String city) {}
    record User(String name, Address address) {
        Optional<Address> addressOpt() { return Optional.ofNullable(address); }
    }

    static Optional<User> findUser(String id) {
        return "u1".equals(id) ? Optional.of(new User("An", new Address("Hanoi")))
                               : Optional.empty();
    }

    public static void main(String[] args) {
        String city = findUser("u1")
                .flatMap(User::addressOpt)      // Optional lồng nhau -> flatMap
                .map(Address::city)
                .orElse("unknown");
        System.out.println(city);                // Hanoi

        // orElseGet: chỉ tính khi thực sự thiếu giá trị
        String name = findUser("u9").map(User::name).orElseGet(() -> "guest");
        System.out.println(name);                // guest

        // biến 'không có' thành lỗi domain rõ ràng
        try {
            findUser("u9").orElseThrow(() -> new IllegalArgumentException("user not found"));
        } catch (IllegalArgumentException e) {
            System.out.println(e.getMessage());
        }
    }
}

